func TestInvestigationRSEWideValues(t *testing.T) {
 for _, index := range []int{0,1,2,3} {
  data := make([]byte,16)
  data[index*4+2] = 1 // 65536 as an int32; currently wraps to zero in an int16
  song := Song{Version: Version{Number:[3]byte{5,1,0}}}
  got, err := song.readRseInstrument(newCursor(data))
  t.Logf("field=%d result=%#v error=%v", index, got, err)
  if err == nil { t.Errorf("RSE int32 field %d silently accepted out-of-range value 65536",index) }
 }
}

